CREATE TABLE users(id BIGSERIAL PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN ('CUSTOMER','SHOP_OWNER')),created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE stores(id BIGSERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,phone VARCHAR(30),address TEXT,business_hours VARCHAR(120));